// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@uniswap/v2-periphery/contracts/interfaces/IUniswapV2Router02.sol";
import "@uniswap/v2-core/contracts/interfaces/IUniswapV2Factory.sol";

contract CALF is ERC20, Ownable, Pausable {
    IUniswapV2Router02 public uniswapRouter;
    address public immutable WETH; // Wrapped ETH 地址

    // 定义每个用户的流动性提供的 ETH 余额
    mapping(address => uint256) public ethBalances;

    // 记录用户是否已经添加流动性
    mapping(address => bool) public hasProvidedLiquidity;

    // 奖励等待时间（以秒计）
    uint256 public constant REWARD_DURATION = 30 days;

    // 奖励的上限，最多领取 500 枚 CALF
    uint256 public constant MAX_REWARD = 500 * (10 ** 18); // 500 枚 CALF

    // 奖励领取的截止时间，2024年12月11日的时间戳
    uint256 public constant rewardClaimStartTime = 1733875200; // 2024年12月11日 00:00:00 UTC

    // 事件定义
    event LiquidityProvided(address indexed user, uint256 ethAmount, uint256 tokenAmount);
    event LiquidityRemoved(address indexed user, uint256 ethAmount, uint256 tokenAmount);
    event RewardClaimed(address indexed user, uint256 amount);

    // 构造函数
    constructor(uint256 initialSupply, address _router) ERC20("CALF", "CALF") Ownable(msg.sender) {
        _mint(msg.sender, initialSupply * (10 ** decimals()));
        uniswapRouter = IUniswapV2Router02(_router);
        WETH = uniswapRouter.WETH();
    }

    // 添加流动性，用户将 ETH 和 CALF 代币提供到流动性池中
    function addLiquidity(uint256 tokenAmount) external payable {
        require(msg.value > 0, "ETH amount must be greater than 0");
        require(tokenAmount > 0, "Token amount must be greater than 0");
        require(!hasProvidedLiquidity[msg.sender], "You have already provided liquidity");

        // 转移 CALF 代币到合约
        _transfer(msg.sender, address(this), tokenAmount);

        // 批准 Uniswap Router 转移代币
        _approve(address(this), address(uniswapRouter), tokenAmount);

        // 添加流动性
        (uint256 amountToken, uint256 amountETH, uint256 liquidity) = uniswapRouter.addLiquidityETH{value: msg.value}(
            address(this), // 代币地址
            tokenAmount,   // 代币数量
            0,             // 最小代币数量
            0,             // 最小 ETH 数量
            msg.sender,    // 流动性提供者地址
            block.timestamp // 截止时间
        );

        // 更新流动性状态
        ethBalances[msg.sender] += amountETH;
        hasProvidedLiquidity[msg.sender] = true;

        emit LiquidityProvided(msg.sender, amountETH, amountToken);
    }

    // 移除流动性并返还 ETH 和代币
    function removeLiquidity(uint256 liquidity) external {
        require(hasProvidedLiquidity[msg.sender], "You have not provided liquidity");

        // 计算要移除的流动性代币
        address pair = IUniswapV2Factory(uniswapRouter.factory()).getPair(address(this), WETH);
        require(pair != address(0), "Liquidity pool does not exist");

        // 转移流动性代币到合约
        IERC20(pair).transferFrom(msg.sender, address(this), liquidity);

        // 移除流动性
        (uint256 amountToken, uint256 amountETH) = uniswapRouter.removeLiquidityETH(
            address(this), // 代币地址
            liquidity,     // 移除的流动性数量
            0,             // 最小代币数量
            0,             // 最小 ETH 数量
            msg.sender,    // 提取流动性后代币接收地址
            block.timestamp // 截止时间
        );

        // 更新流动性状态
        ethBalances[msg.sender] -= amountETH;

        emit LiquidityRemoved(msg.sender, amountETH, amountToken);
    }

    // 领取奖励
    function claimReward() external {
        require(hasProvidedLiquidity[msg.sender], "No liquidity provided");
        require(block.timestamp >= rewardClaimStartTime, "Cannot claim reward before December 11, 2024");

        // 奖励计算（可以根据流动性比例进行调整）
        uint256 reward = ethBalances[msg.sender] * 50;

        // 限制奖励上限为 500 CALF
        if (reward > MAX_REWARD) {
            reward = MAX_REWARD;
        }

        // 铸造奖励代币
        _mint(msg.sender, reward);

        emit RewardClaimed(msg.sender, reward);
    }

    // 合约拥有者铸造更多代币
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    // 查询用户的流动性提供的 ETH 余额
    function getProvidedLiquidityBalance(address user) external view returns (uint256) {
        return ethBalances[user];
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

